def toHex(num: int) -> str:
    if num == 0:
        return "0"

    hexas = "0123456789abcdef"
    result = []

    if num < 0:
        num += 2**32

    while num > 0:
        result.append(hexas[num % 16])
        num //= 16

    result.reverse()
    return ''.join(result)

