def numPrimeArrangements(n: int) -> int:
    MOD = 10**9 + 7

    def sieve_of_eratosthenes(limit):
        is_prime = [True] * (limit + 1)
        is_prime[0] = is_prime[1] = False
        for i in range(2, int(limit**0.5) + 1):
            if is_prime[i]:
                for j in range(i * i, limit + 1, i):
                    is_prime[j] = False
        return sum(is_prime)

    def factorial(x):
        result = 1
        for i in range(2, x + 1):
            result = (result * i) % MOD
        return result

    prime_count = sieve_of_eratosthenes(n)
    non_prime_count = n - prime_count

    return (factorial(prime_count) * factorial(non_prime_count)) % MOD

# Sample Test cases
assert numPrimeArrangements(n=5) == 12

def countLargestGroup(n: int) -> int:
    from collections import defaultdict

    def digit_sum(x):
        return sum(int(d) for d in str(x))

    groups = defaultdict(int)

    for i in range(1, n + 1):
        s = digit_sum(i)
        groups[s] += 1

    max_size = max(groups.values())
    return sum(1 for size in groups.values() if size == max_size)

