def flipLights(n, presses):
    def toggle(state, button):
        if button == 1:
            return [not bulb for bulb in state]
        elif button == 2:
            return [bulb if (i % 2 == 1) else not bulb for i, bulb in enumerate(state)]
        elif button == 3:
            return [bulb if (i % 2 == 0) else not bulb for i, bulb in enumerate(state)]
        elif button == 4:
            return [bulb if (i % 3 != 0) else not bulb for i, bulb in enumerate(state)]

    unique_states = set()
    initial_state = [True] * n

    for i in range(1 << (4 * presses)):
        state = initial_state[:]
        for j in range(presses):
            button = (i >> (j * 4)) & 0b11
            state = toggle(state, button + 1)
        unique_states.add(tuple(state))

    return len(unique_states)

# Sample Test cases
assert flipLights(n=1, presses=1) == 2
assert flipLights(n=2, presses=1) == 3
assert flipLights(n=3, presses=1) == 4

def calculate(s: str) -> int:
    stack = []
    num = 0
    ope = '+'
    s += '+'  # Append a '+' to handle the last number

    for char in s:
        if char.isdigit():
            num = num * 10 + int(char)
        elif char in '+-*/':
            if ope == '+':
                stack.append(num)
            elif ope == '-':
                stack.append(-num)
            elif ope == '*':
                stack[-1] = stack[-1] * num
            elif ope == '/':
                stack[-1] = int(stack[-1] / num)  # Truncate towards zero
            ope = char
            num = 0

    return sum(stack)

