def minSteps(n: int) -> int:
    dp = [0] * (n + 1)

    for i in range(2, n + 1):
        dp[i] = i  # Initialize with the maximum operations (i.e., i pastes)
        for j in range(1, int(i**0.5) + 1):
            if i % j == 0:
                dp[i] = min(dp[i], dp[j] + (i // j))  # Copy All + Paste
                if j != 1:  # Avoid counting the same divisor twice
                    dp[i] = min(dp[i], dp[i // j] + j)  # Copy All + Paste

    return dp[n]

