from collections import defaultdict

class UnionFind:
    def __init__(self, size):
        self.parent = list(range(size))
        self.rank = [1] * size

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])  # Path compression
        return self.parent[x]

    def union(self, x, y):
        rootX = self.find(x)
        rootY = self.find(y)
        if rootX != rootY:
            if self.rank[rootX] > self.rank[rootY]:
                self.parent[rootY] = rootX
            elif self.rank[rootX] < self.rank[rootY]:
                self.parent[rootX] = rootY
            else:
                self.parent[rootY] = rootX
                self.rank[rootX] += 1

def prime_factors(n):
    factors = set()
    # Check for number of 2s that divide n
    while n % 2 == 0:
        factors.add(2)
        n //= 2
    # n must be odd at this point, thus a skip of 2 (i.e., i = i + 2) can be used
    for i in range(3, int(n**0.5) + 1, 2):
        while n % i == 0:
            factors.add(i)
            n //= i
    if n > 2:
        factors.add(n)
    return factors

def canTraverseAllPairs(nums):
    n = len(nums)
    uf = UnionFind(n)

    # Map to store indices of each number
    prime_to_indices = defaultdict(list)

    # Collect indices for each prime factor
    for i in range(n):
        factors = prime_factors(nums[i])
        for factor in factors:
            prime_to_indices[factor].append(i)

    # Union indices based on shared prime factors
    for indices in prime_to_indices.values():
        for i in range(len(indices)):
            for j in range(i + 1, len(indices)):
                uf.union(indices[i], indices[j])

    # Check if all indices are connected
    root = uf.find(0)
    for i in range(1, n):
        if uf.find(i) != root:
            return False

    return True

