def preimageSizeFZF(k):
    def f(x):
        count = 0
        while x > 0:
            x //= 5
            count += x
        return count

    def binary_search(target):
        low, high = 0, 5 * (target + 1)
        while low < high:
            mid = (low + high) // 2
            if f(mid) < target:
                low = mid + 1
            else:
                high = mid
        return low

    first_k = binary_search(k)
    first_k_plus_1 = binary_search(k + 1)

    return first_k_plus_1 - first_k

