def splitArraySameAverage(nums):
    total_sum = sum(nums)
    n = len(nums)

    for k in range(1, n // 2 + 1):
        if total_sum * k % n != 0:
            continue
        target_sum = total_sum * k // n

        dp = [set() for _ in range(k + 1)]
        dp[0].add(0)

        for num in nums:
            for j in range(k, 0, -1):
                for s in dp[j - 1]:
                    dp[j].add(s + num)

        if target_sum in dp[k]:
            return True

    return False

