def nthMagicalNumber(n, a, b):
    mod = 10**9 + 7
    lcm_ab = lcm(a, b)

    low, high = min(a, b), n * max(a, b)

    while low < high:
        mid = (low + high) // 2
        count = (mid // a) + (mid // b) - (mid // lcm_ab)

        if count < n:
            low = mid + 1
        else:
            high = mid

    return low % mod

