assert maximumSum(nums=[8, 10, 3, 8, 1, 13, 7, 9, 4]) == 20

def waysToReachStair(k):
    ways = 0

    def countWays(current, jump):
        nonlocal ways
        if current == k:
            ways += 1
        if current > 0:
            countWays(current - 1, jump)  # Go down
        countWays(current + 2 * jump, jump + 1)  # Go up

    if k == 0:
        return 2
    elif k == 1:
        return 4

    countWays(1, 0)
    return ways

# Sample Test cases
assert waysToReachStair(k=0) == 2
assert waysToReachStair(k=1) == 4

def reachingPoints(sx: int, sy: int, tx: int, ty: int) -> bool:
    while tx >= sx and ty >= sy:
        if tx == sx and (ty - sy) % tx == 0:
            return True
        if ty == sy and (tx - sx) % ty == 0:
            return True
        if tx > ty:
            tx %= ty
        else:
            ty %= tx
    return False

# Sample Test cases
