assert reachingPoints(sx=1, sy=1, tx=2, ty=2) == False
assert reachingPoints(sx=1, sy=1, tx=1, ty=1) == True

def kthCharacter(k, operations):
    length = 1

    for op in operations:
        if op == 0:
            length *= 2
        elif op == 1:
            length *= 2

    current_length = length
    current_char = 'a'

    for op in reversed(operations):
        if op == 0:
            if k > current_length // 2:
                k -= current_length // 2
        elif op == 1:
            if k > current_length // 2:
                k -= current_length // 2
                current_char = chr((ord(current_char) - ord('a') + 1) % 26 + ord('a'))

    return current_char

