def makeStringSorted(s: str) -> int:
    MOD = 10**9 + 7
    operations = 0
    s = list(s)

    def is_sorted(s):
        return all(s[i] <= s[i + 1] for i in range(len(s) - 1))

    while not is_sorted(s):
        i = -1
        for idx in range(1, len(s)):
            if s[idx] < s[idx - 1]:
                i = idx

        if i == -1:
            break

        j = i
        for k in range(i, len(s)):
            if s[k] < s[i - 1]:
                j = k

        s[i - 1], s[j] = s[j], s[i - 1]
        s[i:] = reversed(s[i:])
        operations += 1

    return operations % MOD

# Sample Test cases
assert makeStringSorted(s="cba") == 5
assert makeStringSorted(s="aabaa") == 2

def maximumScore(nums, k):
    from collections import defaultdict
    import math

    MOD = 10**9 + 7

    def prime_factors_count(n):
        count = 0
        if n % 2 == 0:
            count += 1
            while n % 2 == 0:
                n //= 2
        for i in range(3, int(math.sqrt(n)) + 1, 2):
            if n % i == 0:
                count += 1
                while n % i == 0:
                    n //= i
        if n > 2:
            count += 1
        return count

    prime_scores = [prime_factors_count(num) for num in nums]

    candidates = [(prime_scores[i], i, nums[i]) for i in range(len(nums))]
    candidates.sort(key=lambda x: (-x[0], x[1]))

    # Select the top k candidates based on prime score and index
    selected_values = [candidates[i][2] for i in range(min(k, len(candidates)))]

    score = 1
    for value in selected_values:
        score = (score * value) % MOD

    return score

# Sample Test cases
