def is_palindrome(s):
    return s == s[::-1]

def to_base_k(num, k):
    if num == 0:
        return "0"
    digits = []
    while num:
        digits.append(int(num % k))
        num //= k
    return ''.join(str(x) for x in digits[::-1])

def kMirror(k, n):
    k_mirror_numbers = []
    sum_k_mirror = 0
    num = 1

    while len(k_mirror_numbers) < n:
        if is_palindrome(str(num)):
            base_k_representation = to_base_k(num, k)
            if is_palindrome(base_k_representation):
                k_mirror_numbers.append(num)
                sum_k_mirror += num
        num += 1

    return sum_k_mirror

